async function apiRequest(path: string, options: RequestInit = {}) {
  const response = await fetch(`${API_BASE_URL}${path}`, {
    headers: {
      "Content-Type": "application/json",
      ...(options.headers || {}),
    },
    ...options,
  });

  let json: any = null;

  try {
    json = await response.json();
  } catch {
    json = null;
  }

  if (!response.ok || json?.ok === false) {
    throw new Error(json?.message || json?.error || `Error HTTP ${response.status}`);
  }

  return json?.data ?? json;
}

const asArray = <T,>(value: any): T[] => (Array.isArray(value) ? value : []);

const numeric = (value: any) => {
  const number = Number(String(value ?? "").replace(/,/g, ""));
  return Number.isFinite(number) ? number : 0;
};

type SortDirection = "asc" | "desc";

const compareValues = (a: any, b: any, direction: SortDirection) => {
  const av = a ?? "";
  const bv = b ?? "";

  if (typeof av === "number" || typeof bv === "number") {
    const result = Number(av || 0) - Number(bv || 0);
    return direction === "asc" ? result : -result;
  }

  const result = String(av).localeCompare(String(bv), "es", {
    numeric: true,
    sensitivity: "base",
  });

  return direction === "asc" ? result : -result;
};

const formatMoney = (value: any) =>
  new Intl.NumberFormat("es-GT", {
    style: "currency",
    currency: "GTQ",
  }).format(numeric(value));

const todayISO = () => new Date().toISOString().slice(0, 10);

const addDays = (dateString: string, days: number) => {
  const date = dateString ? new Date(`${dateString}T12:00:00`) : new Date();
  date.setDate(date.getDate() + days);
  return date.toISOString().slice(0, 10);
};

const formatDate = (value?: string | null) => {
  if (!value) return "-";
  const date = new Date(`${String(value).slice(0, 10)}T12:00:00`);
  if (Number.isNaN(date.getTime())) return String(value);
  return date.toLocaleDateString("es-GT", {
    year: "numeric",
    month: "short",
    day: "numeric",
  });
};

const normalizeText = (value: unknown) =>
  String(value ?? "")
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "");

const cleanCode = (value: string, max = 20) =>
  value
    .toUpperCase()
    .replace(/[^A-Z0-9-]/g, "")
    .slice(0, max);

const cleanMoneyInput = (value: string, maxInteger = 9, maxDecimals = 2) => {
  const parts = value.replace(/[^0-9.]/g, "").split(".");
  const integer = parts[0].slice(0, maxInteger);
  const decimals = parts.slice(1).join("").slice(0, maxDecimals);
  return parts.length > 1 ? `${integer}.${decimals}` : integer;
};

const cleanInteger = (value: string, maxDigits = 6) =>
  value.replace(/\D/g, "").slice(0, maxDigits);

const cleanDescription = (value: string, max = 180) =>
  value
    .replace(/[^A-Za-zÁÉÍÓÚÜÑáéíóúüñ0-9\s.,#&()'/:+\-]/g, "")
    .replace(/\s+/g, " ")
    .slice(0, max);

const titleCase = (value: string) =>
  value
    .trimStart()
    .toLocaleLowerCase("es-GT")
    .replace(/(^|[\s'-])([a-záéíóúüñ])/g, (_match, sep, letter) =>
      `${sep}${letter.toLocaleUpperCase("es-GT")}`
    )
    .replace(/\bGL365\b/gi, "GL365")
    .replace(/\bSAT\b/gi, "SAT")
    .replace(/\bDTE\b/gi, "DTE");

const cleanReference = (value: string, max = 60) =>
  value
    .toUpperCase()
    .replace(/[^A-Z0-9-]/g, "")
    .slice(0, max);

function createDraft(): DetailDraft {
  return {
    local_id: `${Date.now()}-${Math.random().toString(36).slice(2)}`,
    descripcion: "",
    cantidad: 1,
    unidad: "UN",
    precio_unitario: "",
    descuento_porcentaje: 0,
  };
}

function detalleFromRow(row: DetalleComprobanteRow): DetailDraft {
  const bruto = numeric(row.cantidad) * numeric(row.precio_unitario);
  const descuentoPorcentaje = bruto > 0 ? Math.round((numeric(row.descuento) / bruto) * 100) : 0;
  const allowed = [0, 5, 10, 20];
  const closest = allowed.reduce((best, item) =>
    Math.abs(item - descuentoPorcentaje) < Math.abs(best - descuentoPorcentaje) ? item : best
  );

  return {
    local_id: `${row.id}-${Math.random().toString(36).slice(2)}`,
    descripcion: row.descripcion || "",
    cantidad: numeric(row.cantidad),
    unidad: row.unidad || "UN",
    precio_unitario: numeric(row.precio_unitario),
    descuento_porcentaje: closest,
  };
}

function calcLine(detail: DetailDraft) {
  const cantidad = numeric(detail.cantidad);
  const precio = numeric(detail.precio_unitario);
  const descuentoPct = numeric(detail.descuento_porcentaje);
  const bruto = cantidad * precio;
  const descuento = bruto * (descuentoPct / 100);
  const base = bruto - descuento;
  const iva = base * 0.12;
  const total = base + iva;

  return {
    bruto,
    descuento,
    base,
    iva,
    total,
  };
}

function calcTotals(details: DetailDraft[]) {
  return details.reduce(
    (acc, detail) => {
      const line = calcLine(detail);
      acc.bruto += line.bruto;
      acc.descuento += line.descuento;
      acc.subtotal += line.base;
      acc.iva += line.iva;
      acc.total += line.total;
      return acc;
    },
    { bruto: 0, descuento: 0, subtotal: 0, iva: 0, total: 0 }
  );
}

function estadoTone(estado?: string | null) {
  const text = normalizeText(estado);
  if (text.includes("pagada")) return "bg-green-100 text-green-700 border-green-200";
  if (text.includes("parcial")) return "bg-blue-100 text-blue-700 border-blue-200";
  if (text.includes("vencida")) return "bg-red-100 text-red-700 border-red-200";
  if (text.includes("anulada")) return "bg-gray-100 text-gray-600 border-gray-200";
  return "bg-orange-100 text-orange-700 border-orange-200";
}

function estadoIcon(estado?: string | null) {
  const text = normalizeText(estado);
  if (text.includes("pagada")) return CheckCircle;
  if (text.includes("parcial")) return CircleDollarSign;
  if (text.includes("vencida")) return XCircle;
  if (text.includes("anulada")) return X;
  return Clock;
}

function userName(user?: UsuarioRow | null) {
  if (!user) return "-";
  return (
    user.nombre_completo ||
    [user.primer_nombre, user.segundo_nombre, user.primer_apellido, user.segundo_apellido]
      .filter(Boolean)
      .join(" ") ||
    user.nombre_usuario ||
    "Usuario"
  );
}

