function SearchableSelect<T extends { id: number }>({
  value,
  options,
  placeholder,
  getLabel,
  getSubLabel,
  onSelect,
  disabled,
  error,
}: {
  value: number | "";
  options: T[];
  placeholder: string;
  getLabel: (item: T) => string;
  getSubLabel?: (item: T) => string;
  onSelect: (item: T) => void;
  disabled?: boolean;
  error?: string;
}) {
  const [open, setOpen] = useState(false);
  const [term, setTerm] = useState("");

  const selected = options.find((item) => Number(item.id) === Number(value));
  const filtered = options
    .filter((item) => `${getLabel(item)} ${getSubLabel?.(item) || ""}`.toLowerCase().includes(term.toLowerCase()))
    .slice(0, 30);

  return (
    <div className="relative">
      <button
        type="button"
        disabled={disabled}
        onClick={() => setOpen((current) => !current)}
        className={`${inputClass} flex items-center justify-between text-left ${error ? errorInput : ""}`}
      >
        <span className={selected ? "truncate text-gray-800" : "truncate text-gray-400"}>
          {selected ? getLabel(selected) : placeholder}
        </span>
        <ChevronDown className="h-4 w-4 shrink-0 text-gray-400" />
      </button>

      {open && !disabled && (
        <div className="absolute z-[80] mt-2 w-full overflow-hidden rounded-2xl border border-gray-100 bg-white shadow-xl">
          <div className="border-b border-gray-100 p-2">
            <div className="relative">
              <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-gray-400" />
              <input
                autoFocus
                value={term}
                onChange={(event) => setTerm(event.target.value)}
                className="h-10 w-full rounded-xl bg-gray-50 pl-9 pr-3 text-sm outline-none focus:bg-white focus:ring-2 focus:ring-[#0C2D6B]/10"
                placeholder="Buscar..."
              />
            </div>
          </div>

          <div className="max-h-64 overflow-y-auto p-1">
            {filtered.map((item) => (
              <button
                key={item.id}
                type="button"
                onClick={() => {
                  onSelect(item);
                  setOpen(false);
                  setTerm("");
                }}
                className="w-full rounded-xl px-3 py-2 text-left hover:bg-blue-50"
              >
                <p className="text-sm font-bold text-gray-800">{getLabel(item)}</p>
                {getSubLabel && <p className="text-xs text-gray-400">{getSubLabel(item)}</p>}
              </button>
            ))}

            {!filtered.length && <p className="px-3 py-4 text-center text-sm text-gray-400">Sin resultados</p>}
          </div>
        </div>
      )}
    </div>
  );
}

export function Facturacion() {
  const [clientes, setClientes] = useState<ClienteRow[]>([]);
  const [usuarios, setUsuarios] = useState<UsuarioRow[]>([]);
  const [estadosFactura, setEstadosFactura] = useState<EstadoFacturaRow[]>([]);
  const [formasPago, setFormasPago] = useState<FormaPagoRow[]>([]);
  const [comprobantes, setComprobantes] = useState<ComprobanteRow[]>([]);
  const [detalles, setDetalles] = useState<DetalleComprobanteRow[]>([]);
  const [pagos, setPagos] = useState<PagoRow[]>([]);

  const [search, setSearch] = useState("");
  const [estadoFilter, setEstadoFilter] = useState("Todos");
  const [clienteFilter, setClienteFilter] = useState("Todos");
  const [formaPagoFilter, setFormaPagoFilter] = useState("Todos");
  const [sortField, setSortField] = useState("");
  const [sortDirection, setSortDirection] = useState<SortDirection>("asc");

  const [modalMode, setModalMode] = useState<ModalMode | null>(null);
  const [viewModal, setViewModal] = useState<ComprobanteRow | null>(null);
  const [editComprobante, setEditComprobante] = useState<ComprobanteRow | null>(null);
  const [deleteModal, setDeleteModal] = useState<ComprobanteRow | null>(null);
  const [pagoModal, setPagoModal] = useState<ComprobanteRow | null>(null);

  const [form, setForm] = useState<ComprobanteForm | null>(null);
  const [formErrors, setFormErrors] = useState<FormErrors>({});
  const [pagoForm, setPagoForm] = useState<PagoForm | null>(null);
  const [pagoErrors, setPagoErrors] = useState<FormErrors>({});

  const [loading, setLoading] = useState(false);
  const [apiError, setApiError] = useState("");
  const [notice, setNotice] = useState("");
  const [saving, setSaving] = useState(false);

  const load = async () => {
    setLoading(true);
    setApiError("");

    try {
      const data = await apiRequest("/comprobantes/bootstrap");
      setClientes(asArray<ClienteRow>(data.clientes));
      setUsuarios(asArray<UsuarioRow>(data.usuarios));
      setEstadosFactura(asArray<EstadoFacturaRow>(data.estadosFactura));
      setFormasPago(asArray<FormaPagoRow>(data.formasPago));
      setComprobantes(asArray<ComprobanteRow>(data.comprobantes));
      setDetalles(asArray<DetalleComprobanteRow>(data.detalles));
      setPagos(asArray<PagoRow>(data.pagos));
    } catch (error: any) {
      console.error("Error cargando comprobantes:", error);
      setApiError(error.message || "No se pudo conectar Comprobantes con MySQL.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    void load();
  }, []);

  const showNotice = (message: string) => {
    setNotice(message);
    window.setTimeout(() => setNotice(""), 2800);
  };

  const sortIcon = (field: string) => {
    if (sortField !== field) return "↕";
    return sortDirection === "asc" ? "↑" : "↓";
  };

  const handleSort = (field: string) => {
    if (sortField === field) {
      setSortDirection((prev) => (prev === "asc" ? "desc" : "asc"));
      return;
    }

    setSortField(field);
    setSortDirection("asc");
  };

  const SortableTh = ({
    field,
    children,
    className = "",
  }: {
    field: string;
    children: ReactNode;
    className?: string;
  }) => (
    <th className={className}>
      <button
        type="button"
        onClick={() => handleSort(field)}
        className={`inline-flex items-center gap-0.5 text-[11px] font-bold uppercase tracking-wide transition-colors hover:text-[#FF6A00] ${
          sortField === field ? "text-[#FF6A00]" : "text-gray-500"
        }`}
        title="Ordenar ascendente o descendente"
      >
        <span>{children}</span>
        <span className={`text-[9px] leading-none ${sortField === field ? "text-[#FF6A00]" : "text-gray-300"}`}>
          {sortIcon(field)}
        </span>
      </button>
    </th>
  );

  const getEstadoId = (name: string) =>
    estadosFactura.find((item) => normalizeText(item.nombre_estado_factura).includes(normalizeText(name)))?.id ||
    estadosFactura[0]?.id ||
    "";

  const getFormaDefaultId = () =>
    formasPago.find((item) => normalizeText(item.nombre_forma_pago).includes("transferencia"))?.id ||
    formasPago[0]?.id ||
    "";

  const getUsuarioDefaultId = () => {
    try {
      const saved = JSON.parse(localStorage.getItem("user") || localStorage.getItem("gl365_user") || "null");
      const found = usuarios.find((u) => Number(u.id) === Number(saved?.id));
      if (found) return found.id;
    } catch {
      // noop
    }

    return usuarios[0]?.id || "";
  };

  const detallesByComprobante = (id: number) => detalles.filter((item) => Number(item.comprobante_id) === Number(id));
  const pagosByComprobante = (id: number) => pagos.filter((item) => Number(item.comprobante_id) === Number(id));

  const filteredComprobantes = useMemo(() => {
    const term = normalizeText(search);

    return comprobantes.filter((comprobante) => {
      const text = normalizeText(
        `${comprobante.serie} ${comprobante.numero_comprobante} ${comprobante.cliente} ${comprobante.usuario} ${comprobante.estado} ${comprobante.forma_pago}`
      );

      const matchText = !term || text.includes(term);
      const matchEstado = estadoFilter === "Todos" || Number(comprobante.estado_id) === Number(estadoFilter);
      const matchCliente = clienteFilter === "Todos" || Number(comprobante.cliente_id) === Number(clienteFilter);
      const matchForma = formaPagoFilter === "Todos" || Number(comprobante.forma_pago_id) === Number(formaPagoFilter);

      return matchText && matchEstado && matchCliente && matchForma;
    });
  }, [comprobantes, search, estadoFilter, clienteFilter, formaPagoFilter]);

  const sortedComprobantes = useMemo(() => {
    const rows = [...filteredComprobantes];

    rows.sort((a, b) => {
      const av =
        sortField === "comprobante" ? `${a.serie}-${a.numero_comprobante}` :
        sortField === "cliente" ? a.cliente :
        sortField === "fecha" ? String(a.fecha_emision || "") :
        sortField === "vencimiento" ? String(a.fecha_vencimiento || "") :
        sortField === "total" ? numeric(a.total) :
        sortField === "saldo" ? numeric(a.saldo) :
        sortField === "estado" ? a.estado :
        sortField === "forma" ? a.forma_pago :
        sortField === "emisor" ? a.usuario :
        "";

      const bv =
        sortField === "comprobante" ? `${b.serie}-${b.numero_comprobante}` :
        sortField === "cliente" ? b.cliente :
        sortField === "fecha" ? String(b.fecha_emision || "") :
        sortField === "vencimiento" ? String(b.fecha_vencimiento || "") :
        sortField === "total" ? numeric(b.total) :
        sortField === "saldo" ? numeric(b.saldo) :
        sortField === "estado" ? b.estado :
        sortField === "forma" ? b.forma_pago :
        sortField === "emisor" ? b.usuario :
        "";

      return sortField ? compareValues(av, bv, sortDirection) : 0;
    });

    return rows;
  }, [filteredComprobantes, sortField, sortDirection]);

  const totalGeneral = comprobantes.reduce((sum, item) => sum + numeric(item.total), 0);
  const saldoGeneral = comprobantes.reduce((sum, item) => sum + numeric(item.saldo), 0);
  const pagadas = comprobantes.filter((item) => normalizeText(item.estado).includes("pagada")).length;
  const pendientes = comprobantes.filter((item) => normalizeText(item.estado).includes("pendiente") || normalizeText(item.estado).includes("parcial")).length;
  const vencidas = comprobantes.filter((item) => normalizeText(item.estado).includes("vencida")).length;

  const openCreateModal = () => {
    const emision = todayISO();
    setFormErrors({});
    setForm({
      numero_comprobante: "",
      serie: "GL365-A",
      cliente_id: "",
      usuario_id: getUsuarioDefaultId(),
      fecha_emision: emision,
      fecha_vencimiento: addDays(emision, 15),
      forma_pago_id: getFormaDefaultId(),
      estado_id: getEstadoId("pendiente"),
      observaciones: "",
      detalles: [createDraft()],
    });
    setModalMode("create");
  };

  const openEditModal = (comprobante: ComprobanteRow) => {
    setEditComprobante(comprobante);
    setFormErrors({});
    setForm({
      numero_comprobante: comprobante.numero_comprobante || "",
      serie: comprobante.serie || "GL365-A",
      cliente_id: comprobante.cliente_id || "",
      usuario_id: comprobante.usuario_id || "",
      fecha_emision: String(comprobante.fecha_emision || "").slice(0, 10),
      fecha_vencimiento: String(comprobante.fecha_vencimiento || "").slice(0, 10),
      forma_pago_id: comprobante.forma_pago_id || "",
      estado_id: comprobante.estado_id || "",
      observaciones: comprobante.observaciones || "",
      detalles: detallesByComprobante(comprobante.id).map(detalleFromRow),
    });
    setViewModal(null);
    setModalMode("edit");
  };

  const validateForm = () => {
    if (!form) return false;

    const next: FormErrors = {};

    if (!form.serie) next.serie = "Ingresa la serie.";
    if (!form.cliente_id) next.cliente_id = "Selecciona el cliente.";
    if (!form.usuario_id) next.usuario_id = "Selecciona el emisor.";
    if (!form.fecha_emision) next.fecha_emision = "Selecciona la fecha.";
    if (!form.fecha_vencimiento) next.fecha_vencimiento = "Selecciona el vencimiento.";
    if (!form.forma_pago_id) next.forma_pago_id = "Selecciona la forma de pago.";
    if (!form.estado_id) next.estado_id = "Selecciona el estado.";

    if (!form.detalles.length) next.detalles = "Agrega al menos una línea.";

    form.detalles.forEach((line, index) => {
      if (!line.descripcion.trim()) next[`descripcion_${index}`] = "Descripción obligatoria.";
      if (!numeric(line.cantidad)) next[`cantidad_${index}`] = "Cantidad inválida.";
      if (!line.unidad.trim()) next[`unidad_${index}`] = "Unidad obligatoria.";
      if (line.precio_unitario === "" || numeric(line.precio_unitario) < 0) next[`precio_${index}`] = "Precio inválido.";
    });

    setFormErrors(next);
    return Object.keys(next).length === 0;
  };

  const saveComprobante = async () => {
    if (!form || !validateForm()) return;

    setSaving(true);

    try {
      const payload = {
        ...form,
        numero_comprobante: modalMode === "edit" ? cleanCode(form.numero_comprobante, 20) : form.numero_comprobante,
        serie: cleanCode(form.serie, 15),
        observaciones: cleanDescription(form.observaciones, 255),
        detalles: form.detalles.map((line) => ({
          descripcion: cleanDescription(line.descripcion, 180),
          cantidad: numeric(line.cantidad),
          unidad: cleanCode(line.unidad || "UN", 20) || "UN",
          precio_unitario: numeric(line.precio_unitario),
          descuento_porcentaje: numeric(line.descuento_porcentaje),
        })),
      };

      if (modalMode === "edit" && editComprobante) {
        await apiRequest(`/comprobantes/${editComprobante.id}`, {
          method: "PUT",
          body: JSON.stringify(payload),
        });
        showNotice("Comprobante actualizado correctamente.");
      } else {
        await apiRequest("/comprobantes", {
          method: "POST",
          body: JSON.stringify(payload),
        });
        showNotice("Comprobante guardado correctamente.");
      }

      setModalMode(null);
      setForm(null);
      setEditComprobante(null);
      setFormErrors({});
      await load();
    } catch (error: any) {
      setFormErrors({ general: error.message || "No se pudo guardar el comprobante." });
    } finally {
      setSaving(false);
    }
  };

  const openPagoModal = (comprobante: ComprobanteRow) => {
    setPagoErrors({});
    setPagoModal(comprobante);
    setPagoForm({
      monto: numeric(comprobante.saldo) || "",
      fecha_pago: todayISO(),
      forma_pago_id: comprobante.forma_pago_id || getFormaDefaultId(),
      referencia: "",
    });
  };

  const validatePago = () => {
    if (!pagoForm) return false;

    const next: FormErrors = {};
    if (!pagoForm.monto || numeric(pagoForm.monto) <= 0) next.monto = "Ingresa un monto válido.";
    if (!pagoForm.fecha_pago) next.fecha_pago = "Selecciona la fecha.";
    if (!pagoForm.forma_pago_id) next.forma_pago_id = "Selecciona la forma de pago.";

    setPagoErrors(next);
    return Object.keys(next).length === 0;
  };

  const savePago = async () => {
    if (!pagoModal || !pagoForm || !validatePago()) return;

    setSaving(true);

    try {
      await apiRequest(`/comprobantes/${pagoModal.id}/pagos`, {
        method: "POST",
        body: JSON.stringify({
          monto: numeric(pagoForm.monto),
          fecha_pago: pagoForm.fecha_pago,
          forma_pago_id: pagoForm.forma_pago_id,
          referencia: cleanReference(pagoForm.referencia, 60),
        }),
      });

      setPagoModal(null);
      setPagoForm(null);
      setPagoErrors({});
      await load();
      showNotice("Pago registrado correctamente.");
    } catch (error: any) {
      setPagoErrors({ general: error.message || "No se pudo registrar el pago." });
    } finally {
      setSaving(false);
    }
  };

  const deleteComprobante = async () => {
    if (!deleteModal) return;

    setSaving(true);
    setApiError("");

    try {
      await apiRequest(`/comprobantes/${deleteModal.id}`, { method: "DELETE" });
      setDeleteModal(null);
      await load();
      showNotice("Comprobante eliminado correctamente.");
    } catch (error: any) {
      setApiError(error.message || "No se pudo eliminar el comprobante.");
    } finally {
      setSaving(false);
    }
  };

  const clearFilters = () => {
    setSearch("");
    setEstadoFilter("Todos");
    setClienteFilter("Todos");
    setFormaPagoFilter("Todos");
    setSortField("");
    setSortDirection("asc");
  };

  const exportReportPDF = () => {
    const doc = new jsPDF();
    doc.setFillColor(12, 45, 107);
    doc.rect(0, 0, 210, 30, "F");
    doc.setTextColor(255, 255, 255);
    doc.setFontSize(16);
    doc.text("Grupo Logístico 365", 14, 14);
    doc.setFontSize(10);
    doc.text("Reporte de comprobantes", 14, 22);

    const table = sortedComprobantes.map((item) => [
      `${item.serie}-${item.numero_comprobante}`,
      item.cliente || "-",
      formatDate(item.fecha_emision),
      formatMoney(item.total),
      item.estado || "-",
      formatMoney(item.saldo),
    ]);

    autoTable(doc, {
      startY: 40,
      head: [["Comprobante", "Cliente", "Fecha", "Total", "Estado", "Saldo"]],
      body: table,
      styles: { fontSize: 8, cellPadding: 2 },
      headStyles: { fillColor: [255, 106, 0], textColor: [255, 255, 255] },
    });

    const finalY = (doc as any).lastAutoTable?.finalY || 45;
    doc.setTextColor(12, 45, 107);
    doc.setFontSize(10);
    doc.text(`Total comprobantes: ${sortedComprobantes.length}`, 14, finalY + 12);
    doc.text(`Total facturado: ${formatMoney(sortedComprobantes.reduce((sum, item) => sum + numeric(item.total), 0))}`, 14, finalY + 18);
    doc.save(`Reporte_Comprobantes_${Date.now()}.pdf`);
  };

  const exportExcel = () => {
    const ws = XLSX.utils.json_to_sheet(
      sortedComprobantes.map((item) => ({
        Comprobante: `${item.serie}-${item.numero_comprobante}`,
        Cliente: item.cliente,
        NIT: item.cliente_nit,
        Fecha: item.fecha_emision,
        Vencimiento: item.fecha_vencimiento,
        Subtotal: numeric(item.subtotal),
        IVA: numeric(item.iva),
        Total: numeric(item.total),
        Pagado: numeric(item.pagado),
        Saldo: numeric(item.saldo),
        Estado: item.estado,
        "Forma de pago": item.forma_pago,
        Emisor: item.usuario,
      }))
    );

    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Comprobantes");
    XLSX.writeFile(wb, `Reporte_Comprobantes_${Date.now()}.xlsx`);
  };

  const exportComprobantePDF = (comprobante: ComprobanteRow) => {
    const doc = new jsPDF({
      orientation: "portrait",
      unit: "mm",
      format: "a4",
    });

    const rows = detallesByComprobante(comprobante.id);
    const pagosComprobante = pagosByComprobante(comprobante.id);

    const naranja: [number, number, number] = [255, 127, 0];
    const negro: [number, number, number] = [0, 0, 0];

    const serieDte = serieDtePdf(comprobante);
    const numeroDte = numeroDtePdf(comprobante);
    const autorizacion = autorizacionDtePdf(comprobante);
    const totalFactura = numeric(comprobante.total);
    const fechaEmision = fechaDtePdf(comprobante.fecha_emision);
    const fechaVencimiento = comprobante.fecha_vencimiento
      ? String(comprobante.fecha_vencimiento).slice(0, 10)
      : "-";

    doc.setProperties({
      title: `Factura Cambiaria ${serieDte}-${numeroDte}`,
      subject: "Documento Tributario Electronico",
      author: "Grupo Logistico 365",
      creator: "GL365 ERP",
    });

    doc.setTextColor(...negro);
    doc.setDrawColor(...negro);
    doc.setLineWidth(0.35);

    // Folio
    doc.setFont("helvetica", "normal");
    doc.setFontSize(7.2);
    doc.text("Folio 1 de 1", 204, 7, { align: "right" });

    // Encabezado izquierdo
    doc.setFont("helvetica", "bold");
    doc.setFontSize(15.2);
    doc.text("GRUPO LOGISTICO 365", 6, 14);

    doc.setFontSize(9.6);
    doc.text("GRUPO LOGISTICO 365, SOCIEDAD", 6, 21);
    doc.text("ANONIMA", 6, 26);

    doc.setFontSize(7.2);
    doc.text("KILOMETRO 15 CA 9 MANZANA X, ZONA 6, CONDOMINIO", 6, 33);
    doc.text("SANTA CATALINA CASA-04", 6, 37);
    doc.text("VILLA NUEVA, GUATEMALA", 6, 41);
    doc.text("NIT: 115963375", 6, 45);
    doc.text("Telefono: 00-502-56305639", 6, 49);

    // Logo real del prototipo/referencia
    drawLogoFacturaPdf(doc, 74, 5.5, 43);

    // Cuadro DTE derecho
    doc.setFont("helvetica", "bold");
    doc.setFontSize(8.6);
    doc.text("Documento Tributario Electronico", 174, 10, {
      align: "center",
    });

    const dteX = 144;
    const dteY = 13;
    const dteW = 60;
    const dteH = 39;

    doc.setLineWidth(0.4);
    doc.roundedRect(dteX, dteY, dteW, dteH, 7, 7);

    doc.setFillColor(...naranja);
    doc.roundedRect(dteX, dteY, dteW, 8, 7, 7, "F");
    doc.rect(dteX, dteY + 4, dteW, 4, "F");

    doc.setFont("helvetica", "bold");
    doc.setFontSize(8.3);
    doc.text("Factura Cambiaria", dteX + dteW / 2, dteY + 5.4, {
      align: "center",
    });

    const dteRows = [
      ["Serie:", serieDte],
      ["Numero de DTE:", numeroDte],
      ["Fecha de emision:", fechaEmision],
      ["Moneda:", "GTQ"],
    ];

    doc.setFontSize(7);
    dteRows.forEach(([label, value], index) => {
      const yy = dteY + 15 + index * 6.2;

      doc.setFont("helvetica", "bold");
      doc.text(label, dteX + 8, yy, { align: "left" });
      doc.text(value, dteX + dteW - 8, yy, { align: "right" });
    });

    // NIT
    const nitY = 55;
    const nitX = 6;
    const nitW = 54;
    const nitLabelW = 18;

    doc.roundedRect(nitX, nitY, nitW, 8.5, 4, 4);
    doc.line(nitX + nitLabelW, nitY, nitX + nitLabelW, nitY + 8.5);

    doc.setFont("helvetica", "bold");
    doc.setFontSize(7.5);
    doc.text("NIT", nitX + nitLabelW / 2, nitY + 5.4, { align: "center" });

    drawFitTextFactura(
      doc,
      String(comprobante.cliente_nit || "C/F").toUpperCase(),
      nitX + nitLabelW + (nitW - nitLabelW) / 2,
      nitY + 5.4,
      nitW - nitLabelW - 3,
      { align: "center", maxSize: 6.3, minSize: 4.4 }
    );

    // Datos cliente
    const clientY = 66;
    doc.roundedRect(6, clientY, 198, 10, 2, 2);

    doc.setFontSize(7.1);
    doc.setFont("helvetica", "normal");

    doc.text("Nombre:", 7.2, clientY + 4.2);
    doc.text("Direccion:", 7.2, clientY + 8.1);
    doc.text("Telefono:", 135.5, clientY + 4.2);
    doc.text("Email:", 135.5, clientY + 8.1);

    drawFitTextFactura(
      doc,
      upperPdf(comprobante.cliente),
      26,
      clientY + 4.2,
      104,
      { maxSize: 7.1, minSize: 4.8 }
    );

    drawFitTextFactura(
      doc,
      upperPdf(comprobante.cliente_direccion || "GUATEMALA, GUATEMALA"),
      26,
      clientY + 8.1,
      104,
      { maxSize: 7.1, minSize: 4.8 }
    );

    drawFitTextFactura(
      doc,
      String(comprobante.cliente_telefono || "Sin teléfono"),
      154,
      clientY + 4.2,
      47,
      { maxSize: 7.1, minSize: 4.8 }
    );

    drawFitTextFactura(
      doc,
      String(comprobante.cliente_email || "Sin correo"),
      154,
      clientY + 8.1,
      47,
      { maxSize: 7.1, minSize: 4.5 }
    );

    // Banda naranja de titulos
    const headerY = 79;
    const headerX = 6;
    const headerW = 198;
    const headerH = 9.5;

    doc.setFillColor(...naranja);
    doc.setDrawColor(...negro);
    doc.setLineWidth(0.4);
    doc.roundedRect(headerX, headerY, headerW, headerH, 5, 5, "FD");

    const widths = [19.5, 19.5, 74.5, 23, 21, 22, 18.5];
    const edges = [headerX];
    widths.forEach((w) => edges.push(edges[edges.length - 1] + w));

    const centers = widths.map((_, index) => (edges[index] + edges[index + 1]) / 2);

    doc.setTextColor(...negro);
    doc.setFont("helvetica", "bold");
    doc.setFontSize(7.1);

    doc.text("Cantidad", centers[0], headerY + 5.7, { align: "center" });
    doc.text("Unidad M.", centers[1], headerY + 5.7, { align: "center" });
    doc.text("Descripcion", centers[2], headerY + 5.7, { align: "center" });
    doc.text("P. Unitario\ncon IVA", centers[3], headerY + 4.4, { align: "center" });
    doc.text("Impuestos", centers[4], headerY + 5.7, { align: "center" });
    doc.text("Descuento", centers[5], headerY + 5.7, { align: "center" });
    doc.text("Total", centers[6], headerY + 5.7, { align: "center" });

    const detalleRows =
      rows.length > 0
        ? rows
        : [
            {
              id: 0,
              comprobante_id: comprobante.id,
              descripcion: "SERVICIO LOGISTICO",
              cantidad: 1,
              unidad: "UN",
              precio_unitario: totalFactura,
              impuesto: numeric(comprobante.iva),
              descuento: 0,
              total: totalFactura,
            } as DetalleComprobanteRow,
          ];

    const body = detalleRows.map((line) => {
      const cantidad = numeric(line.cantidad) || 1;
      const totalLinea = numeric(line.total);
      const unitarioConIva = cantidad > 0 ? totalLinea / cantidad : totalLinea;

      return [
        cantidad.toFixed(2),
        line.unidad || "UN",
        upperPdf(line.descripcion),
        moneyFacturaPdf(unitarioConIva),
        `IVA = GTQ ${numeric(line.impuesto).toLocaleString("en-US", {
          minimumFractionDigits: 4,
          maximumFractionDigits: 4,
        })}`,
        moneyFacturaPdf(line.descuento),
        moneyFacturaPdf(totalLinea),
      ];
    });

    autoTable(doc, {
      startY: headerY + headerH + 1.7,
      margin: {
        left: headerX,
        right: 6,
      },
      body,
      theme: "grid",
      showHead: "never",
      tableWidth: headerW,
      styles: {
        fontSize: 6.15,
        textColor: [0, 0, 0],
        lineColor: [0, 0, 0],
        lineWidth: 0.25,
        cellPadding: 1.55,
        valign: "middle",
        minCellHeight: 9.2,
      },
      columnStyles: {
        0: { cellWidth: widths[0], halign: "center" },
        1: { cellWidth: widths[1], halign: "center" },
        2: { cellWidth: widths[2], halign: "left" },
        3: { cellWidth: widths[3], halign: "right" },
        4: { cellWidth: widths[4], halign: "center", fontSize: 4.7 },
        5: { cellWidth: widths[5], halign: "right", fontSize: 5.8 },
        6: { cellWidth: widths[6], halign: "right", fontSize: 5.8 },
      },
    });

    let y = ((doc as any).lastAutoTable?.finalY || 101) + 2;

    // Total en letras y total
    const totalBoxH = 10.5;
    doc.setLineWidth(0.4);
    doc.roundedRect(6, y, 198, totalBoxH, 5, 5);

    const totalDividerX = 146;
    doc.line(totalDividerX, y, totalDividerX, y + totalBoxH);

    doc.setFont("helvetica", "bold");
    doc.setFontSize(5.75);

    const letras = `TOTAL EN LETRAS: ${numeroALetrasGTQPdf(totalFactura)}`;
    const letrasLines = doc.splitTextToSize(letras, 137);
    doc.text(letrasLines.slice(0, 2), 9, y + 4.2);

    doc.setFontSize(7.5);
    doc.text("Total:", 162, y + 6.2, { align: "center" });

    doc.setFont("helvetica", "normal");
    doc.text(moneyFacturaPdf(totalFactura), 202, y + 6.2, {
      align: "right",
    });

    // ISR
    y += 17;
    doc.setFont("helvetica", "normal");
    doc.setFontSize(7.2);
    doc.text("- Sujeto a pagos trimestrales ISR", 8, y);

    // Abono
    y += 7;
    const abonoH = 14.5;
    doc.roundedRect(6, y, 198, abonoH, 5, 5);

    doc.setFontSize(7);
    doc.text(`Numero de abono: ${pagosComprobante.length || 1}`, 8.2, y + 4.5);
    doc.text(`Fecha de vencimiento: ${fechaVencimiento}`, 8.2, y + 8.9);
    doc.text(`Monto del abono: ${moneyFacturaPdf(totalFactura)}`, 8.2, y + 13.1);

    // Autorizacion
    y += 18.5;
    doc.roundedRect(8, y, 96, 7.5, 4, 4);
    doc.setFontSize(6.8);
    doc.text(`AUTORIZACION: ${autorizacion}`.slice(0, 67), 9.5, y + 4.7);

    // Certificador
    y += 12;
    doc.setFontSize(7);
    doc.text("NOMBRE DEL CERTIFICADOR: Grupo CDS, S.A.", 8, y);
    doc.text("NIT: 107902281", 8, y + 6);
    doc.text(`FECHA: ${fechaEmision}`, 8, y + 12);

    // QR visual
    drawQrFacturaPdf(doc, 8, y + 18, 24, comprobante.id);

    doc.save(`Factura_Cambiaria_${serieDte}_${numeroDte}.pdf`);
  };

  return (
    <div className="w-full min-w-0 max-w-[calc(100vw-17rem)] space-y-5 overflow-x-hidden px-2 sm:px-3 pb-10">
      <div className="flex min-w-0 flex-col gap-4 rounded-3xl border border-gray-100 bg-white p-5 shadow-sm lg:flex-row lg:items-center lg:justify-between">
        <div className="min-w-0">
          <p className="text-xs font-bold uppercase tracking-[0.25em] text-[#FF6A00]">Facturación</p>
          <h1 className="mt-1 text-3xl font-bold text-[#0C2D6B]">Comprobantes</h1>
          <p className="mt-1 max-w-3xl text-gray-500">Gestión de comprobantes, detalle de servicios y control de pagos</p>
        </div>

        <div className="flex flex-wrap gap-2">
          <button
            type="button"
            onClick={load}
            disabled={loading}
            className="inline-flex h-11 items-center gap-2 rounded-xl border border-gray-200 bg-white px-4 text-sm font-bold text-[#0C2D6B] shadow-sm disabled:opacity-60"
          >
            <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} />
            {loading ? "Cargando..." : "Actualizar"}
          </button>

          <button
            type="button"
            onClick={openCreateModal}
            className="inline-flex h-11 items-center gap-2 rounded-xl bg-[#0C2D6B] px-4 text-sm font-bold text-white shadow-sm hover:bg-[#143C8C]"
          >
            <Plus className="h-4 w-4" />
            Nuevo Comprobante
          </button>
        </div>
      </div>

      {apiError && <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-semibold text-red-700">{apiError}</div>}
      {notice && <div className="rounded-xl border border-green-200 bg-green-50 px-4 py-3 text-sm font-semibold text-green-700">{notice}</div>}

      <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4">
        <KpiCard title="Total facturado" value={formatMoney(totalGeneral)} icon={ReceiptText} bar="bg-[#0C2D6B]" subtitle={`${comprobantes.length} comprobantes`} />
        <KpiCard title="Pagadas" value={pagadas} icon={CheckCircle} bar="bg-green-500" />
        <KpiCard title="Pendientes" value={pendientes} icon={Clock} bar="bg-[#FF6A00]" />
        <KpiCard title="Saldo por cobrar" value={formatMoney(saldoGeneral)} icon={WalletCards} bar={vencidas > 0 ? "bg-red-500" : "bg-blue-500"} subtitle={`${vencidas} vencidas`} />
      </div>

      <div className="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm">
        <div className="grid grid-cols-1 gap-3 lg:grid-cols-2 xl:grid-cols-[minmax(220px,1fr)_175px_210px_190px_105px_90px_100px]">
          <div className="relative min-w-0">
            <Search className="absolute left-4 top-1/2 h-5 w-5 -translate-y-1/2 text-gray-400" />
            <input
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder="Buscar por número, cliente, emisor o forma de pago..."
              className="h-11 w-full rounded-xl border border-gray-200 bg-white pl-12 pr-4 text-sm outline-none shadow-sm focus:border-[#0C2D6B] focus:ring-2 focus:ring-[#0C2D6B]/20"
            />
          </div>

          <select value={estadoFilter} onChange={(event) => setEstadoFilter(event.target.value)} className="h-11 w-full rounded-xl border border-gray-200 bg-white px-4 text-sm outline-none shadow-sm focus:border-[#0C2D6B] focus:ring-2 focus:ring-[#0C2D6B]/20">
            <option value="Todos">Todos los estados</option>
            {estadosFactura.map((estado) => (
              <option key={estado.id} value={estado.id}>{estado.nombre_estado_factura}</option>
            ))}
          </select>

          <select value={clienteFilter} onChange={(event) => setClienteFilter(event.target.value)} className="h-11 w-full rounded-xl border border-gray-200 bg-white px-4 text-sm outline-none shadow-sm focus:border-[#0C2D6B] focus:ring-2 focus:ring-[#0C2D6B]/20">
            <option value="Todos">Todos los clientes</option>
            {clientes.map((cliente) => (
              <option key={cliente.id} value={cliente.id}>{cliente.nombre_empresa}</option>
            ))}
          </select>

          <select value={formaPagoFilter} onChange={(event) => setFormaPagoFilter(event.target.value)} className="h-11 w-full rounded-xl border border-gray-200 bg-white px-4 text-sm outline-none shadow-sm focus:border-[#0C2D6B] focus:ring-2 focus:ring-[#0C2D6B]/20">
            <option value="Todos">Todas las formas</option>
            {formasPago.map((forma) => (
              <option key={forma.id} value={forma.id}>{forma.nombre_forma_pago}</option>
            ))}
          </select>

          <button type="button" onClick={clearFilters} className="inline-flex h-11 items-center justify-center gap-1.5 rounded-xl border border-orange-200 bg-white px-3 text-sm font-bold text-[#FF6A00] shadow-sm transition hover:border-[#FF6A00] hover:bg-orange-50 whitespace-nowrap">
            <X className="h-4 w-4" /> Limpiar
          </button>

          <button type="button" onClick={exportReportPDF} className="inline-flex h-11 items-center justify-center gap-1.5 rounded-xl bg-red-500 px-3 text-sm font-bold text-white shadow-sm hover:bg-red-600 whitespace-nowrap">
            <FileText className="h-4 w-4" /> PDF
          </button>

          <button type="button" onClick={exportExcel} className="inline-flex h-11 items-center justify-center gap-1.5 rounded-xl bg-[#22C55E] px-3 text-sm font-bold text-white shadow-sm hover:bg-[#16A34A] whitespace-nowrap">
            <Download className="h-4 w-4" /> Excel
          </button>
        </div>

        <div className="mt-3 flex flex-wrap items-center gap-2">
          <span className="text-sm font-bold text-gray-400">
            {sortedComprobantes.length} de {comprobantes.length} registros visibles
          </span>
          <span className="hidden sm:inline text-xs font-semibold text-gray-300">·</span>
          <span className="text-xs font-semibold text-gray-400">
            Ordená tocando los encabezados de la tabla.
          </span>
        </div>
      </div>

      <div className="min-w-0 max-w-full overflow-hidden rounded-2xl border border-gray-100 bg-white shadow-sm">
        <div className="w-full max-w-full overflow-x-auto">
          <table className="w-full min-w-[1040px] text-left text-[12.5px]">
            <thead className="border-b border-gray-100 bg-gray-50 text-[11px] uppercase tracking-wide text-gray-400">
              <tr>
                <SortableTh field="comprobante" className="px-3 py-3">Comprobante</SortableTh>
                <SortableTh field="cliente" className="px-3 py-3">Cliente</SortableTh>
                <SortableTh field="fecha" className="px-3 py-3">Fecha</SortableTh>
                <SortableTh field="total" className="px-3 py-3">Total</SortableTh>
                <SortableTh field="saldo" className="px-3 py-3">Saldo</SortableTh>
                <SortableTh field="estado" className="px-3 py-3">Estado</SortableTh>
                <SortableTh field="forma" className="px-3 py-3">Forma</SortableTh>
                <SortableTh field="emisor" className="px-3 py-3">Emisor</SortableTh>
                <th className="px-3 py-3 text-right">Acciones</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {sortedComprobantes.map((comprobante) => (
                <tr key={comprobante.id} className="hover:bg-gray-50/70">
                  <td className="px-3 py-3">
                    <p className="font-mono font-bold text-[#0C2D6B]">{comprobante.serie}-{comprobante.numero_comprobante}</p>
                    <p className="text-xs text-gray-400">Vence: {formatDate(comprobante.fecha_vencimiento)}</p>
                  </td>
                  <td className="px-3 py-3">
                    <p className="max-w-[190px] truncate font-semibold text-gray-800">{comprobante.cliente || "-"}</p>
                    <p className="text-xs text-gray-400">NIT: {comprobante.cliente_nit || "C/F"}</p>
                  </td>
                  <td className="px-3 py-3 text-gray-600">{formatDate(comprobante.fecha_emision)}</td>
                  <td className="px-3 py-3 font-bold text-gray-800">{formatMoney(comprobante.total)}</td>
                  <td className="px-3 py-3 font-bold text-[#0C2D6B]">{formatMoney(comprobante.saldo)}</td>
                  <td className="px-3 py-3"><Badge estado={comprobante.estado} /></td>
                  <td className="px-3 py-3 text-gray-600">
                    <p className="max-w-[95px] break-words leading-5">{comprobante.forma_pago || "-"}</p>
                  </td>
                  <td className="px-3 py-3 text-gray-500">
                    <p className="max-w-[110px] break-words leading-5">{comprobante.usuario || "-"}</p>
                  </td>
                  <td className="px-3 py-3">
                    <div className="flex justify-end gap-1">
                      <ActionButton title="Ver" icon={Eye} tone="blue" onClick={() => setViewModal(comprobante)} />
                      <ActionButton title="Editar" icon={Edit2} tone="orange" onClick={() => { setViewModal(comprobante); openEditModal(comprobante); }} />
                      <ActionButton title="Registrar pago" icon={CreditCard} tone="green" onClick={() => openPagoModal(comprobante)} />
                      <ActionButton title="Descargar PDF" icon={Download} onClick={() => exportComprobantePDF(comprobante)} />
                      <ActionButton title="Eliminar" icon={Trash2} tone="red" onClick={() => setDeleteModal(comprobante)} />
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>

        {!sortedComprobantes.length && (
          <div className="p-10 text-center text-gray-500">
            <ReceiptText className="mx-auto mb-3 h-12 w-12 text-gray-300" />
            No se encontraron comprobantes.
          </div>
        )}
      </div>

      {modalMode && form && (
        <ComprobanteModal
          mode={modalMode}
          form={form}
          setForm={setForm}
          errors={formErrors}
          setErrors={setFormErrors}
          clientes={clientes}
          usuarios={usuarios}
          estadosFactura={estadosFactura}
          formasPago={formasPago}
          saving={saving}
          onClose={() => {
            setModalMode(null);
            setForm(null);
            setFormErrors({});
            setViewModal(null);
            setEditComprobante(null);
          }}
          onSave={saveComprobante}
        />
      )}

      {viewModal && !modalMode && (
        <DetalleComprobanteModal
          comprobante={viewModal}
          detalles={detallesByComprobante(viewModal.id)}
          pagos={pagosByComprobante(viewModal.id)}
          onClose={() => setViewModal(null)}
          onEdit={() => openEditModal(viewModal)}
          onPago={() => openPagoModal(viewModal)}
          onPDF={() => exportComprobantePDF(viewModal)}
        />
      )}

      {pagoModal && pagoForm && (
        <PagoModal
          comprobante={pagoModal}
          form={pagoForm}
          setForm={setPagoForm}
          errors={pagoErrors}
          setErrors={setPagoErrors}
          formasPago={formasPago}
          saving={saving}
          onClose={() => {
            setPagoModal(null);
            setPagoForm(null);
            setPagoErrors({});
          }}
          onSave={savePago}
        />
      )}

      {deleteModal && (
        <ConfirmDelete
          comprobante={deleteModal}
          loading={saving}
          onCancel={() => !saving && setDeleteModal(null)}
          onConfirm={deleteComprobante}
        />
      )}
    </div>
  );
}

function ComprobanteModal({
  mode,
  form,
  setForm,
  errors,
  setErrors,
  clientes,
  usuarios,
  estadosFactura,
  formasPago,
  saving,
  onClose,
  onSave,
}: {
  mode: ModalMode;
  form: ComprobanteForm;
  setForm: Dispatch<SetStateAction<ComprobanteForm | null>>;
  errors: FormErrors;
  setErrors: Dispatch<SetStateAction<FormErrors>>;
  clientes: ClienteRow[];
  usuarios: UsuarioRow[];
  estadosFactura: EstadoFacturaRow[];
  formasPago: FormaPagoRow[];
  saving: boolean;
  onClose: () => void;
  onSave: () => void;
}) {
  const totals = calcTotals(form.detalles);

  const updateForm = (patch: Partial<ComprobanteForm>) => setForm((current) => (current ? { ...current, ...patch } : current));
  const clearError = (field: string) => setErrors((prev) => ({ ...prev, [field]: "" }));

  const updateLine = (index: number, patch: Partial<DetailDraft>) => {
    const next = form.detalles.map((line, i) => (i === index ? { ...line, ...patch } : line));
    updateForm({ detalles: next });
  };

  const addLine = () => updateForm({ detalles: [...form.detalles, createDraft()] });
  const removeLine = (index: number) => {
    if (form.detalles.length <= 1) return;
    updateForm({ detalles: form.detalles.filter((_line, i) => i !== index) });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-start justify-center overflow-y-auto bg-black/45 p-2 sm:p-4 backdrop-blur-sm">
      <div className="my-2 flex max-h-[90vh] w-full max-w-[980px] flex-col overflow-hidden rounded-3xl bg-white shadow-2xl">
        <div className="flex shrink-0 items-center justify-between gap-3 border-b border-gray-100 px-4 py-3">
          <div>
            <h2 className="text-xl font-bold text-[#0C2D6B]">{mode === "create" ? "Nuevo Comprobante" : "Editar Comprobante"}</h2>
            <p className="mt-0.5 text-xs text-gray-400">Serie, cliente, detalle de servicio y forma de pago</p>
          </div>

          <button type="button" onClick={onClose} className="inline-flex h-9 w-9 items-center justify-center rounded-full bg-gray-50 text-gray-400 hover:bg-gray-100 hover:text-gray-700">
            <X className="h-5 w-5" />
          </button>
        </div>

        {errors.general && <div className="mx-5 mt-4 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-semibold text-red-700">{errors.general}</div>}

        <div data-form onKeyDown={moveOnEnter} className="min-h-0 overflow-y-auto px-4 py-4">
          {mode === "create" && (
            <div className="mb-4 rounded-2xl border border-blue-100 bg-blue-50 p-4">
              <p className="text-sm font-bold text-[#0C2D6B]">Número automático</p>
              <p className="mt-1 text-xs text-gray-600">El sistema asignará el correlativo al guardar. Solo debes seleccionar cliente, emisor y líneas del comprobante.</p>
            </div>
          )}

          <div className="grid grid-cols-1 gap-3 md:grid-cols-2 lg:grid-cols-4">
            <Field label="Serie *" error={errors.serie}>
              <input value={form.serie} maxLength={15} onChange={(event) => { updateForm({ serie: cleanCode(event.target.value, 15) }); clearError("serie"); }} className={`${inputClass} ${errors.serie ? errorInput : ""}`} placeholder="GL365-A" />
            </Field>

            {mode === "edit" && (
              <Field label="Número *" error={errors.numero_comprobante}>
                <input value={form.numero_comprobante} maxLength={20} onChange={(event) => { updateForm({ numero_comprobante: cleanCode(event.target.value, 20) }); clearError("numero_comprobante"); }} className={`${inputClass} ${errors.numero_comprobante ? errorInput : ""}`} placeholder="000001" />
              </Field>
            )}

            <Field label="Fecha emisión *" error={errors.fecha_emision}>
              <input type="date" value={form.fecha_emision} onChange={(event) => { updateForm({ fecha_emision: event.target.value, fecha_vencimiento: form.fecha_vencimiento || addDays(event.target.value, 15) }); clearError("fecha_emision"); }} className={`${inputClass} ${errors.fecha_emision ? errorInput : ""}`} />
            </Field>

            <Field label="Vencimiento *" error={errors.fecha_vencimiento}>
              <input type="date" value={form.fecha_vencimiento} onChange={(event) => { updateForm({ fecha_vencimiento: event.target.value }); clearError("fecha_vencimiento"); }} className={`${inputClass} ${errors.fecha_vencimiento ? errorInput : ""}`} />
            </Field>

            <Field label="Cliente *" error={errors.cliente_id} className="md:col-span-2">
              <SearchableSelect
                value={form.cliente_id}
                options={clientes}
                placeholder="Buscar cliente..."
                getLabel={(cliente) => cliente.nombre_empresa}
                getSubLabel={(cliente) => `${cliente.codigo_cliente} · NIT ${cliente.nit}`}
                onSelect={(cliente) => { updateForm({ cliente_id: cliente.id }); clearError("cliente_id"); }}
                error={errors.cliente_id}
              />
            </Field>

            <Field label="Emisor *" error={errors.usuario_id}>
              <SearchableSelect
                value={form.usuario_id}
                options={usuarios}
                placeholder="Buscar emisor..."
                getLabel={(usuario) => userName(usuario)}
                getSubLabel={(usuario) => usuario.email || usuario.nombre_usuario || "Usuario GL365"}
                onSelect={(usuario) => { updateForm({ usuario_id: usuario.id }); clearError("usuario_id"); }}
                error={errors.usuario_id}
              />
            </Field>

            <Field label="Estado *" error={errors.estado_id}>
              <select value={form.estado_id} onChange={(event) => { updateForm({ estado_id: event.target.value ? Number(event.target.value) : "" }); clearError("estado_id"); }} className={`${inputClass} ${errors.estado_id ? errorInput : ""}`}>
                <option value="">Seleccionar</option>
                {estadosFactura.map((estado) => <option key={estado.id} value={estado.id}>{estado.nombre_estado_factura}</option>)}
              </select>
            </Field>

            <Field label="Forma de pago *" error={errors.forma_pago_id} className="md:col-span-2">
              <select value={form.forma_pago_id} onChange={(event) => { updateForm({ forma_pago_id: event.target.value ? Number(event.target.value) : "" }); clearError("forma_pago_id"); }} className={`${inputClass} ${errors.forma_pago_id ? errorInput : ""}`}>
                <option value="">Seleccionar forma</option>
                {formasPago.map((forma) => <option key={forma.id} value={forma.id}>{forma.nombre_forma_pago}</option>)}
              </select>
            </Field>
          </div>

          <div className="mt-4 rounded-2xl border border-gray-100 bg-gray-50 p-3">
            <div className="mb-3 flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
              <div>
                <h3 className="text-sm font-bold text-[#0C2D6B]">Detalle del comprobante</h3>
                <p className="text-xs text-gray-400">Cantidad, unidad, descripción, precio y descuento</p>
              </div>
              <button type="button" onClick={addLine} className="inline-flex h-10 w-fit items-center gap-2 rounded-xl bg-[#0C2D6B] px-4 text-xs font-bold text-white">
                <Plus className="h-4 w-4" /> Agregar línea
              </button>
            </div>

            <div className="space-y-3">
              {form.detalles.map((line, index) => {
                const calc = calcLine(line);
                return (
                  <div key={line.local_id} className="rounded-2xl border border-gray-100 bg-white p-3">
                    <div className="grid grid-cols-1 gap-2 md:grid-cols-12">
                      <Field label="Cant. *" error={errors[`cantidad_${index}`]} className="md:col-span-1">
                        <input inputMode="numeric" value={line.cantidad} onChange={(event) => { const clean = cleanInteger(event.target.value, 6); updateLine(index, { cantidad: clean === "" ? "" : Number(clean) }); clearError(`cantidad_${index}`); }} className={`${inputClass} ${errors[`cantidad_${index}`] ? errorInput : ""}`} />
                      </Field>

                      <Field label="Unidad *" error={errors[`unidad_${index}`]} className="md:col-span-2">
                        <select value={line.unidad} onChange={(event) => { updateLine(index, { unidad: cleanCode(event.target.value, 20) }); clearError(`unidad_${index}`); }} className={`${inputClass} ${errors[`unidad_${index}`] ? errorInput : ""}`}>
                          <option value="UN">UN</option>
                          <option value="KG">KG</option>
                          <option value="SERV">SERV</option>
                          <option value="VIAJE">VIAJE</option>
                          <option value="FLETE">FLETE</option>
                        </select>
                      </Field>

                      <Field label="Descripción *" error={errors[`descripcion_${index}`]} className="md:col-span-5">
                        <input value={line.descripcion} onChange={(event) => { updateLine(index, { descripcion: titleCase(cleanDescription(event.target.value, 180)) }); clearError(`descripcion_${index}`); }} className={`${inputClass} ${errors[`descripcion_${index}`] ? errorInput : ""}`} placeholder="Servicio logístico..." />
                      </Field>

                      <Field label="P. Unitario *" error={errors[`precio_${index}`]} className="md:col-span-2">
                        <input inputMode="decimal" value={line.precio_unitario} onChange={(event) => { const clean = cleanMoneyInput(event.target.value, 8, 2); updateLine(index, { precio_unitario: clean === "" ? "" : Number(clean) }); clearError(`precio_${index}`); }} className={`${inputClass} ${errors[`precio_${index}`] ? errorInput : ""}`} placeholder="0.00" />
                      </Field>

                      <Field label="Desc." className="md:col-span-1">
                        <select value={line.descuento_porcentaje} onChange={(event) => updateLine(index, { descuento_porcentaje: Number(event.target.value) })} className={inputClass}>
                          <option value={0}>0%</option>
                          <option value={5}>5%</option>
                          <option value={10}>10%</option>
                          <option value={20}>20%</option>
                        </select>
                      </Field>

                      <div className="flex items-end justify-end md:col-span-1">
                        <button type="button" onClick={() => removeLine(index)} disabled={form.detalles.length <= 1} className="inline-flex h-11 w-11 items-center justify-center rounded-xl border border-red-100 bg-red-50 text-red-600 disabled:cursor-not-allowed disabled:opacity-40">
                          <Minus className="h-4 w-4" />
                        </button>
                      </div>
                    </div>

                    <div className="mt-2 grid grid-cols-2 gap-2 text-xs sm:grid-cols-4">
                      <MiniTotal label="Subtotal" value={formatMoney(calc.bruto)} />
                      <MiniTotal label="Descuento" value={formatMoney(calc.descuento)} />
                      <MiniTotal label="IVA" value={formatMoney(calc.iva)} />
                      <MiniTotal label="Total" value={formatMoney(calc.total)} strong />
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          <div className="mt-4 grid grid-cols-1 gap-3 lg:grid-cols-3">
            <Field label="Observaciones" className="lg:col-span-2">
              <textarea rows={4} value={form.observaciones} onChange={(event) => updateForm({ observaciones: cleanDescription(event.target.value, 255) })} className={`${inputClass} h-auto resize-none py-3`} placeholder="Observaciones del comprobante..." />
            </Field>

            <div className="rounded-2xl border border-[#0C2D6B]/10 bg-[#0C2D6B] p-4 text-white">
              <p className="text-xs font-bold uppercase tracking-wide text-blue-100">Resumen</p>
              <div className="mt-3 space-y-2 text-sm">
                <SummaryLine label="Subtotal bruto" value={formatMoney(totals.bruto)} />
                <SummaryLine label="Descuento" value={formatMoney(totals.descuento)} />
                <SummaryLine label="Base" value={formatMoney(totals.subtotal)} />
                <SummaryLine label="IVA 12%" value={formatMoney(totals.iva)} />
                <div className="border-t border-white/20 pt-3">
                  <SummaryLine label="Total" value={formatMoney(totals.total)} strong />
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="flex shrink-0 justify-end gap-2 border-t border-gray-100 bg-gray-50 px-4 py-3">
          <button type="button" onClick={onClose} className="h-10 rounded-xl border border-gray-200 bg-white px-4 text-sm font-bold text-gray-700 hover:bg-gray-100">Cancelar</button>
          <button data-save-button="true" type="button" onClick={onSave} disabled={saving} className="inline-flex h-10 items-center gap-2 rounded-xl bg-[#0C2D6B] px-5 text-sm font-bold text-white hover:bg-[#143C8C] disabled:opacity-60">
            {saving ? <RefreshCw className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
            {saving ? "Guardando..." : "Guardar"}
          </button>
        </div>
      </div>
    </div>
  );
}

function MiniTotal({ label, value, strong }: { label: string; value: string; strong?: boolean }) {
  return (
    <div className="rounded-xl bg-gray-50 px-3 py-2">
      <p className="text-[10px] font-bold uppercase text-gray-400">{label}</p>
      <p className={`mt-1 ${strong ? "font-bold text-[#0C2D6B]" : "font-semibold text-gray-700"}`}>{value}</p>
    </div>
  );
}

function SummaryLine({ label, value, strong }: { label: string; value: string; strong?: boolean }) {
  return (
    <div className="flex justify-between gap-3">
      <span className={strong ? "text-base font-bold" : "text-blue-100"}>{label}</span>
      <span className={strong ? "text-lg font-bold" : "font-semibold"}>{value}</span>
    </div>
  );
}

function DetalleComprobanteModal({ comprobante, detalles, pagos, onClose, onEdit, onPago, onPDF }: { comprobante: ComprobanteRow; detalles: DetalleComprobanteRow[]; pagos: PagoRow[]; onClose: () => void; onEdit: () => void; onPago: () => void; onPDF: () => void }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/45 p-3 backdrop-blur-sm">
      <div className="flex max-h-[94vh] w-full max-w-4xl flex-col overflow-hidden rounded-3xl bg-white shadow-2xl">
        <div className="flex items-center justify-between gap-3 border-b border-gray-100 px-5 py-4">
          <div>
            <h2 className="text-xl font-bold text-[#0C2D6B]">Detalle de Comprobante</h2>
            <p className="mt-0.5 font-mono text-sm font-bold text-[#FF6A00]">{comprobante.serie}-{comprobante.numero_comprobante}</p>
          </div>
          <button type="button" onClick={onClose} className="inline-flex h-9 w-9 items-center justify-center rounded-full bg-gray-50 text-gray-400 hover:bg-gray-100 hover:text-gray-700">
            <X className="h-5 w-5" />
          </button>
        </div>

        <div className="overflow-y-auto p-5">
          <div className="grid grid-cols-1 gap-4 lg:grid-cols-3">
            <div className="lg:col-span-2 rounded-2xl border border-gray-100 bg-gray-50 p-4">
              <p className="text-xs font-bold uppercase tracking-wide text-gray-400">Cliente</p>
              <h3 className="mt-1 text-xl font-bold text-gray-800">{comprobante.cliente || "-"}</h3>
              <p className="mt-1 text-sm text-gray-500">NIT: {comprobante.cliente_nit || "C/F"}</p>
              <p className="text-sm text-gray-500">{comprobante.cliente_direccion || "Guatemala"}</p>
            </div>

            <div className="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm">
              <Badge estado={comprobante.estado} />
              <p className="mt-4 text-xs font-bold uppercase tracking-wide text-gray-400">Total</p>
              <p className="text-2xl font-bold text-[#0C2D6B]">{formatMoney(comprobante.total)}</p>
              <p className="mt-2 text-sm text-gray-500">Saldo: <b>{formatMoney(comprobante.saldo)}</b></p>
            </div>
          </div>

          <div className="mt-4 grid grid-cols-1 gap-3 md:grid-cols-4">
            <Info label="Fecha emisión" value={formatDate(comprobante.fecha_emision)} />
            <Info label="Vencimiento" value={formatDate(comprobante.fecha_vencimiento)} />
            <Info label="Forma de pago" value={comprobante.forma_pago || "-"} />
            <Info label="Emisor" value={comprobante.usuario || "-"} />
          </div>

          <div className="mt-5 overflow-hidden rounded-2xl border border-gray-100">
            <div className="bg-gray-50 px-4 py-3">
              <h3 className="text-sm font-bold text-[#0C2D6B]">Detalle de servicios</h3>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full min-w-[720px] text-left text-sm">
                <thead className="border-b border-gray-100 text-[11px] uppercase tracking-wide text-gray-400">
                  <tr>
                    <th className="px-3 py-3">Cant.</th>
                    <th className="px-3 py-3">Unidad</th>
                    <th className="px-3 py-3">Descripción</th>
                    <th className="px-3 py-3">P. Unitario</th>
                    <th className="px-3 py-3">IVA</th>
                    <th className="px-3 py-3">Descuento</th>
                    <th className="px-3 py-3">Total</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-100">
                  {detalles.map((line) => (
                    <tr key={line.id}>
                      <td className="px-3 py-3">{numeric(line.cantidad).toFixed(2)}</td>
                      <td className="px-3 py-3">{line.unidad}</td>
                      <td className="px-4 py-3 font-semibold text-gray-800">{line.descripcion}</td>
                      <td className="px-3 py-3">{formatMoney(line.precio_unitario)}</td>
                      <td className="px-3 py-3">{formatMoney(line.impuesto)}</td>
                      <td className="px-3 py-3">{formatMoney(line.descuento)}</td>
                      <td className="px-3 py-3 font-bold text-[#0C2D6B]">{formatMoney(line.total)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="mt-5 grid grid-cols-1 gap-4 lg:grid-cols-2">
            <div className="rounded-2xl border border-gray-100 bg-white p-4">
              <h3 className="text-sm font-bold text-[#0C2D6B]">Pagos registrados</h3>
              <div className="mt-3 space-y-2">
                {pagos.map((pago) => (
                  <div key={pago.id} className="rounded-xl bg-gray-50 px-3 py-2">
                    <div className="flex justify-between gap-3">
                      <p className="font-bold text-gray-800">{formatMoney(pago.monto)}</p>
                      <p className="text-sm text-gray-500">{formatDate(pago.fecha_pago)}</p>
                    </div>
                    <p className="text-xs text-gray-400">{pago.forma_pago || "-"} · Ref. {pago.referencia || "S/R"}</p>
                  </div>
                ))}
                {!pagos.length && <p className="text-sm text-gray-400">No existen pagos registrados.</p>}
              </div>
            </div>

            <div className="rounded-2xl border border-[#0C2D6B]/10 bg-[#0C2D6B] p-4 text-white">
              <p className="text-xs font-bold uppercase tracking-wide text-blue-100">Resumen</p>
              <div className="mt-3 space-y-2 text-sm">
                <SummaryLine label="Subtotal" value={formatMoney(comprobante.subtotal)} />
                <SummaryLine label="IVA" value={formatMoney(comprobante.iva)} />
                <SummaryLine label="Total" value={formatMoney(comprobante.total)} />
                <SummaryLine label="Pagado" value={formatMoney(comprobante.pagado)} />
                <div className="border-t border-white/20 pt-3">
                  <SummaryLine label="Saldo" value={formatMoney(comprobante.saldo)} strong />
                </div>
              </div>
            </div>
          </div>
        </div>

        <div className="flex flex-wrap justify-end gap-2 border-t border-gray-100 bg-gray-50 px-5 py-4">
          <button type="button" onClick={onEdit} className="inline-flex h-10 items-center gap-2 rounded-xl border border-orange-100 bg-orange-50 px-4 text-sm font-bold text-[#FF6A00]"><Edit2 className="h-4 w-4" /> Editar</button>
          <button type="button" onClick={onPago} className="inline-flex h-10 items-center gap-2 rounded-xl border border-green-100 bg-green-50 px-4 text-sm font-bold text-green-700"><CreditCard className="h-4 w-4" /> Pago</button>
          <button type="button" onClick={onPDF} className="inline-flex h-10 items-center gap-2 rounded-xl bg-[#0C2D6B] px-4 text-sm font-bold text-white"><Download className="h-4 w-4" /> PDF</button>
        </div>
      </div>
    </div>
  );
}

function Info({ label, value }: { label: string; value: any }) {
  return (
    <div className="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm">
      <p className="text-[11px] font-bold uppercase tracking-wide text-gray-400">{label}</p>
      <p className="mt-1 break-words font-semibold text-gray-800">{value || "-"}</p>
    </div>
  );
}

function PagoModal({ comprobante, form, setForm, errors, setErrors, formasPago, saving, onClose, onSave }: { comprobante: ComprobanteRow; form: PagoForm; setForm: Dispatch<SetStateAction<PagoForm | null>>; errors: FormErrors; setErrors: Dispatch<SetStateAction<FormErrors>>; formasPago: FormaPagoRow[]; saving: boolean; onClose: () => void; onSave: () => void }) {
  const updateForm = (patch: Partial<PagoForm>) => setForm((current) => (current ? { ...current, ...patch } : current));
  const clearError = (field: string) => setErrors((prev) => ({ ...prev, [field]: "" }));

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/45 p-3 backdrop-blur-sm">
      <div className="w-full max-w-xl overflow-hidden rounded-3xl bg-white shadow-2xl">
        <div className="flex items-center justify-between gap-3 border-b border-gray-100 px-5 py-4">
          <div>
            <h2 className="text-xl font-bold text-[#0C2D6B]">Registrar pago</h2>
            <p className="mt-0.5 font-mono text-sm font-bold text-[#FF6A00]">{comprobante.serie}-{comprobante.numero_comprobante}</p>
          </div>
          <button type="button" onClick={onClose} className="inline-flex h-9 w-9 items-center justify-center rounded-full bg-gray-50 text-gray-400 hover:bg-gray-100 hover:text-gray-700">
            <X className="h-5 w-5" />
          </button>
        </div>

        {errors.general && <div className="mx-5 mt-4 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm font-semibold text-red-700">{errors.general}</div>}

        <div data-form onKeyDown={moveOnEnter} className="p-5">
          <div className="mb-4 rounded-2xl border border-green-100 bg-green-50 p-4">
            <p className="text-sm font-bold text-green-700">Saldo actual: {formatMoney(comprobante.saldo)}</p>
            <p className="mt-1 text-xs text-gray-600">El estado se actualiza automáticamente según el total pagado.</p>
          </div>

          <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
            <Field label="Monto *" error={errors.monto}>
              <input inputMode="decimal" value={form.monto} onChange={(event) => { const clean = cleanMoneyInput(event.target.value, 9, 2); updateForm({ monto: clean === "" ? "" : Number(clean) }); clearError("monto"); }} className={`${inputClass} ${errors.monto ? errorInput : ""}`} placeholder="0.00" />
            </Field>

            <Field label="Fecha de pago *" error={errors.fecha_pago}>
              <input type="date" value={form.fecha_pago} onChange={(event) => { updateForm({ fecha_pago: event.target.value }); clearError("fecha_pago"); }} className={`${inputClass} ${errors.fecha_pago ? errorInput : ""}`} />
            </Field>

            <Field label="Forma de pago *" error={errors.forma_pago_id} className="md:col-span-2">
              <select value={form.forma_pago_id} onChange={(event) => { updateForm({ forma_pago_id: event.target.value ? Number(event.target.value) : "" }); clearError("forma_pago_id"); }} className={`${inputClass} ${errors.forma_pago_id ? errorInput : ""}`}>
                <option value="">Seleccionar forma</option>
                {formasPago.map((forma) => <option key={forma.id} value={forma.id}>{forma.nombre_forma_pago}</option>)}
              </select>
            </Field>

            <Field label="Referencia" className="md:col-span-2">
              <input value={form.referencia} onChange={(event) => updateForm({ referencia: cleanReference(event.target.value, 60) })} className={inputClass} placeholder="TRANSFERENCIA-123" />
            </Field>
          </div>
        </div>

        <div className="flex justify-end gap-2 border-t border-gray-100 bg-gray-50 px-5 py-4">
          <button type="button" onClick={onClose} className="h-10 rounded-xl border border-gray-200 bg-white px-4 text-sm font-bold text-gray-700 hover:bg-gray-100">Cancelar</button>
          <button data-save-button="true" type="button" onClick={onSave} disabled={saving} className="inline-flex h-10 items-center gap-2 rounded-xl bg-[#0C2D6B] px-5 text-sm font-bold text-white hover:bg-[#143C8C] disabled:opacity-60">
            {saving ? <RefreshCw className="h-4 w-4 animate-spin" /> : <CreditCard className="h-4 w-4" />}
            {saving ? "Guardando..." : "Guardar pago"}
          </button>
        </div>
      </div>
    </div>
  );
}

function ConfirmDelete({ comprobante, loading, onCancel, onConfirm }: { comprobante: ComprobanteRow; loading: boolean; onCancel: () => void; onConfirm: () => void }) {
  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center bg-black/50 p-4 backdrop-blur-sm">
      <div className="w-full max-w-md overflow-hidden rounded-3xl border border-gray-100 bg-white shadow-2xl">
        <div className="h-2 bg-red-500" />
        <div className="p-6">
          <div className="flex items-start gap-4">
            <div className="flex h-14 w-14 shrink-0 items-center justify-center rounded-2xl bg-red-50 text-red-600">
              <Trash2 className="h-7 w-7" />
            </div>
            <div className="min-w-0 flex-1">
              <h3 className="text-xl font-bold text-[#0C2D6B]">Eliminar comprobante</h3>
              <p className="mt-1 text-sm leading-relaxed text-gray-500">Esta acción eliminará el comprobante, sus líneas de detalle y pagos relacionados.</p>
              <div className="mt-4 rounded-2xl border border-gray-100 bg-gray-50 px-4 py-3">
                <p className="text-[11px] font-bold uppercase tracking-wide text-gray-400">Registro seleccionado</p>
                <p className="mt-1 font-mono text-sm font-bold text-gray-800">{comprobante.serie}-{comprobante.numero_comprobante}</p>
              </div>
            </div>
            <button type="button" onClick={onCancel} disabled={loading} className="inline-flex h-9 w-9 items-center justify-center rounded-full bg-gray-50 text-gray-400 hover:bg-gray-100 hover:text-gray-700 disabled:opacity-60">
              <X className="h-5 w-5" />
            </button>
          </div>
        </div>
        <div className="flex flex-col-reverse gap-2 border-t border-gray-100 bg-gray-50 px-6 py-4 sm:flex-row sm:justify-end">
          <button type="button" onClick={onCancel} disabled={loading} className="h-11 rounded-xl border border-gray-200 bg-white px-5 text-sm font-bold text-gray-700 hover:bg-gray-100 disabled:opacity-60">Cancelar</button>
          <button type="button" onClick={onConfirm} disabled={loading} className="inline-flex h-11 items-center justify-center gap-2 rounded-xl bg-red-600 px-5 text-sm font-bold text-white shadow-sm hover:bg-red-700 disabled:opacity-60">
            {loading ? <RefreshCw className="h-4 w-4 animate-spin" /> : <Trash2 className="h-4 w-4" />}
            {loading ? "Eliminando..." : "Sí, eliminar"}
          </button>
        </div>
      </div>
    </div>
  );
}

export default Facturacion;